return ['project-id-version'=>'PN Customers Manager','report-msgid-bugs-to'=>'','pot-creation-date'=>'2024-07-31 14:21+0000','po-revision-date'=>'2026-11-02 17:59+0000','last-translator'=>'Sea Suite Spain','language-team'=>'Catalan','language'=>'ca','plural-forms'=>'nplurals=2; plural=n != 1;','mime-version'=>'1.0','content-type'=>'text/plain; charset=UTF-8','content-transfer-encoding'=>'8bit','x-generator'=>'Loco https://localise.biz/','x-loco-version'=>'2.8.9; wp-7.1.4; php-8.2.35','x-domain'=>'crmpn','messages'=>['"%s" in Group %d must be a valid email'=>'"%s" del Grup %d ha de ser un correu electrònic vàlid','"%s" is required in Group %d of %s'=>'Cal "%s" al Grup %d de %s','%1$s has invited you to join %2$s. Click the button below to accept the invitation and set up your account.'=>'%1$s t\'ha convidat a unir-te a %2$s. Fes clic al botó següent per acceptar la invitació i configurar el teu compte.','%1$s has requested to be notified when the product \'%2$s\' is back in stock.'=>'%1$s ha sol·licitat ser notificat quan el producte \'%2$s\' torni a estar disponible.','%d invoice'=>'Factura %d' . "\0" . '%d factures','%d orders completed successfully'=>'%d comandes completades correctament','%d pending orders found'=>'S\'han trobat %d comandes pendents','%d pending orders found with QR products'=>'S\'han trobat %d comandes pendents amb productes amb codi QR','%d QR codes deleted'=>'%d codis QR suprimits','%d QR codes marked as pending'=>'%d codis QR marcats com a pendents','%d QR codes marked as processed'=>'%d codis QR marcats com a processats','%d user(s) assigned the role successfully.'=>'S\'ha assignat correctament el rol a %d usuaris.','%d user(s) removed from the role successfully.'=>'S\'ha eliminat correctament %d usuari(s) del rol.','%s API Key has not been configured.'=>'No s\'ha configurat la clau API %s.','%s API key is not configured. Please go to Settings > PN Customers Manager > API Configuration > AI Providers and configure your API key.'=>'La clau API %s no està configurada. Aneu a Configuració > Gestor de clients de PN > Configuració de l\'API > Proveïdors d\'IA i configureu la vostra clau API.','%s Generator'=>'Generador %s','%s has invited you!'=>'%s t\'ha convidat!','%s is back in stock'=>'%s ja està disponible','%s is back in stock!'=>'%s ja està disponible!','%s is required.'=>'Cal %s.','%s slug'=>'%s llimac','%s te ha invitado!'=>'%s t\'han convidat!','+ Add Field'=>'+ Afegeix un camp','-- Seleccionar frase --'=>'-- Seleccionar frase --','-- Select --'=>'-- Selecciona --','-- Select a category --'=>'-- Selecciona una categoria --','-- Select funnel --'=>'-- Selecciona l\'embut --','-- Select template --'=>'-- Selecciona una plantilla --','-- Use global --'=>'-- Utilitza global --','0 = cold lead, 100 = hot lead.'=>'0 = plom fred, 100 = plom calent.','1 - 10 people'=>'1 - 10 persones','1 year'=>'1 any','11 - 50 people'=>'11 - 50 persones','201 - 500 people'=>'201 - 500 persones','24 h'=>'24 hores','25-45'=>'25-45','30 days'=>'30 dies',5=>'5',500=>'500','51 - 200 people'=>'51 - 200 persones','7 days'=>'7 dies','<strong>How to configure it:</strong><br>1. Create any secret string (e.g.: <code>my_ig_token_2024</code>) and type it here.<br>2. Save the settings.<br>3. When configuring the webhook on Meta, use exactly the same string as the &laquo;Verify Token&raquo;.'=>'<strong>Com configurar-ho:</strong><br> 1. Crea qualsevol cadena secreta (per exemple: <code>my_ig_token_2024</code> ) i escriu-la aquí.<br> 2. Desa la configuració.<br> 3. Quan configureu el webhook a Meta, feu servir exactament la mateixa cadena que el «Verify Token».','<strong>How to configure it:</strong><br>1. Create any secret string (e.g.: <code>my_secure_token_2024</code>) and type it here.<br>2. Save the settings.<br>3. When configuring the webhook on Meta (below), you will be asked for a &laquo;Verify Token&raquo;: use exactly the same string.<br>Meta will send a GET request with this token to verify that the webhook is yours.'=>'<strong>Com configurar-ho:</strong><br> 1. Crea qualsevol cadena secreta (per exemple: <code>my_secure_token_2024</code> ) i escriu-la aquí.<br> 2. Desa la configuració.<br> 3. Quan configureu el webhook a Meta (a continuació), se us demanarà un «Verify Token»: utilitzeu exactament la mateixa cadena.<br> Meta enviarà una sol·licitud GET amb aquest token per verificar que el webhook és vostre.','<strong>How to configure the webhook on Meta:</strong><br>1. Copy the URL shown above.<br>2. Go to <a href="https://developers.facebook.com/apps/" target="_blank">Meta for Developers</a> &gt; your app &gt; Instagram &gt; Webhooks.<br>3. Paste the URL in the &laquo;Callback URL&raquo; field.<br>4. In &laquo;Verify Token&raquo; type the same token you configured above.<br>5. Click &laquo;Verify and Save&raquo;.<br>6. Subscribe to the <code>messages</code> webhook field.'=>'<strong>Com configurar el webhook a Meta:</strong><br> 1. Copieu l&#39;URL que es mostra a dalt.<br> 2. Ves a <a href="https://developers.facebook.com/apps/" target="_blank">Meta per a desenvolupadors</a> &gt; la teva aplicació &gt; Instagram &gt; Webhooks.<br> 3. Enganxeu l&#39;URL al camp «URL de devolució de trucada».<br> 4. A «Verifica el token», escriu el mateix token que has configurat anteriorment.<br> 5. Feu clic a «Verifica i desa».<br> 6. Subscriu-te al camp webhook <code>messages</code> .','<strong>How to configure the webhook on Meta:</strong><br>1. Copy the URL shown above.<br>2. Go to <a href="https://developers.facebook.com/apps/" target="_blank">Meta for Developers</a> &gt; your app &gt; WhatsApp &gt; Configuration.<br>3. In the &laquo;Webhook&raquo; section, click &laquo;Edit&raquo;.<br>4. Paste the URL in the &laquo;Callback URL&raquo; field.<br>5. In &laquo;Verify Token&raquo; type the same token you configured above.<br>6. Click &laquo;Verify and Save&raquo;.<br>7. In &laquo;Webhook fields&raquo;, subscribe to the <code>messages</code> field.'=>'<strong>Com configurar el webhook a Meta:</strong><br> 1. Copieu l&#39;URL que es mostra a dalt.<br> 2. Ves a <a href="https://developers.facebook.com/apps/" target="_blank">Meta per a desenvolupadors</a> &gt; la teva aplicació &gt; WhatsApp &gt; Configuració.<br> 3. A la secció «Webhook», feu clic a «Edita».<br> 4. Enganxeu l&#39;URL al camp «URL de devolució de trucada».<br> 5. A «Verifica el token», escriu el mateix token que has configurat anteriorment.<br> 6. Feu clic a «Verifica i desa».<br> 7. A «Camps del Webhook», subscriviu-vos al camp <code>messages</code> .','<strong>How to get it (temporary token):</strong><br>1. Go to <a href="https://developers.facebook.com/apps/" target="_blank">Meta for Developers</a> &gt; your app &gt; WhatsApp &gt; API Setup.<br>2. In the &laquo;Temporary access token&raquo; section, click <strong>Generate</strong> and copy the token. <em>Expires in ~24 hours.</em><br><br><strong>Permanent token (recommended for production):</strong><br>1. Go to <a href="https://business.facebook.com/settings/" target="_blank">Meta Business Suite</a> &gt; Settings &gt; Business settings.<br>2. Under <strong>Users &gt; System Users</strong>, create a System User of type <em>Admin</em>.<br>3. Assign the WhatsApp App asset to it.<br>4. Generate a token with the <code>whatsapp_business_messaging</code> permission.<br>5. This token does not expire and does not need renewal.'=>'<strong>Com aconseguir-ho (token temporal):</strong><br> 1. Ves a <a href="https://developers.facebook.com/apps/" target="_blank">Meta per a desenvolupadors</a> &gt; la teva aplicació &gt; WhatsApp &gt; Configuració de l&#39;API.<br> 2. A la secció «Token d&#39;accés temporal», feu clic a <strong>Genera</strong> i copieu el token. <em>Caduca en unes 24 hores.</em><br><br> <strong>Token permanent (recomanat per a producció):</strong><br> 1. Aneu a <a href="https://business.facebook.com/settings/" target="_blank">Meta Business Suite</a> &gt; Configuració &gt; Configuració empresarial.<br> 2. A <strong>Usuaris &gt; Usuaris del sistema</strong> , creeu un usuari del sistema de tipus <em>Administrador</em> .<br> 3. Assigneu-hi l&#39;actiu de l&#39;aplicació WhatsApp.<br> 4. Genera un token amb el permís <code>whatsapp_business_messaging</code> .<br> 5. Aquest token no caduca i no cal renovar-lo.','<strong>How to get it:</strong><br>1. Go to <a href="https://dashscope.console.aliyun.com/apiKey" target="_blank">DashScope Console</a>.<br>2. Create a new API key and paste it here.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Aneu a <a href="https://dashscope.console.aliyun.com/apiKey" target="_blank">la consola de DashScope</a> .<br> 2. Crea una nova clau API i enganxa-la aquí.','<strong>How to get it:</strong><br>1. Go to <a href="https://developers.facebook.com/apps/" target="_blank">Meta for Developers</a> &gt; your app &gt; Instagram &gt; API Setup.<br>2. Copy the Instagram-scoped Page ID (numeric ID) and paste it here.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Ves a <a href="https://developers.facebook.com/apps/" target="_blank">Meta per a desenvolupadors</a> &gt; la teva aplicació &gt; Instagram &gt; Configuració de l&#39;API.<br> 2. Copieu l&#39;ID de pàgina amb àmbit d&#39;Instagram (ID numèric) i enganxeu-lo aquí.','<strong>How to get it:</strong><br>1. Go to <a href="https://developers.facebook.com/apps/" target="_blank">Meta for Developers</a> &gt; your app &gt; Instagram &gt; API Setup.<br>2. Generate an access token with <code>instagram_manage_messages</code> permission.<br><br><strong>Permanent token (recommended):</strong><br>Use a System User token from <a href="https://business.facebook.com/settings/" target="_blank">Meta Business Suite</a> with <code>instagram_manage_messages</code> permission.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Ves a <a href="https://developers.facebook.com/apps/" target="_blank">Meta per a desenvolupadors</a> &gt; la teva aplicació &gt; Instagram &gt; Configuració de l&#39;API.<br> 2. Genera un token d&#39;accés amb permís <code>instagram_manage_messages</code> .<br><br> <strong>Token permanent (recomanat):</strong><br> Utilitzeu un token d&#39;usuari del sistema de <a href="https://business.facebook.com/settings/" target="_blank">Meta Business Suite</a> amb permís <code>instagram_manage_messages</code> .','<strong>How to get it:</strong><br>1. Go to <a href="https://developers.facebook.com/apps/" target="_blank">Meta for Developers</a> &gt; your app &gt; WhatsApp &gt; API Setup.<br>2. In the &laquo;From&raquo; section your phone number appears with its <strong>Phone number ID</strong> below.<br>3. Copy the numeric ID (e.g.: <code>123456789012345</code>) and paste it here.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Ves a <a href="https://developers.facebook.com/apps/" target="_blank">Meta per a desenvolupadors</a> &gt; la teva aplicació &gt; WhatsApp &gt; Configuració de l&#39;API.<br> 2. A la secció «De», apareixerà el vostre número de telèfon amb el seu <strong>identificador</strong> a sota.<br> 3. Copieu l&#39;ID numèric (per exemple: <code>123456789012345</code> ) i enganxeu-lo aquí.','<strong>How to get it:</strong><br>1. Go to <a href="https://platform.deepseek.com/api_keys" target="_blank">platform.deepseek.com/api_keys</a>.<br>2. Create a new API key and paste it here.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Aneu a <a href="https://platform.deepseek.com/api_keys" target="_blank">platform.deepseek.com/api_keys</a> .<br> 2. Crea una nova clau API i enganxa-la aquí.','<strong>How to get it:</strong><br>1. Go to <a href="https://platform.moonshot.cn/console/api-keys" target="_blank">Moonshot Platform</a>.<br>2. Create a new API key and paste it here.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Ves a <a href="https://platform.moonshot.cn/console/api-keys" target="_blank">la plataforma Moonshot</a> .<br> 2. Crea una nova clau API i enganxa-la aquí.','<strong>How to get it:</strong><br>1. Go to <a href="https://platform.openai.com/api-keys" target="_blank">platform.openai.com/api-keys</a>.<br>2. Click &laquo;Create new secret key&raquo;.<br>3. Copy the generated key (starts with <code>sk-</code>) and paste it here.'=>'<strong>Com aconseguir-ho:</strong><br> 1. Aneu a <a href="https://platform.openai.com/api-keys" target="_blank">platform.openai.com/api-keys</a> .<br> 2. Feu clic a «Crea una nova clau secreta».<br> 3. Copieu la clau generada (que comença amb <code>sk-</code> ) i enganxeu-la aquí.','[%1$s] New order via %2$s'=>'[%1$s] Nova comanda a través de %2$s','[%1$s] Special order request via %2$s'=>'[%1$s] Sol·licitud de comanda especial a través de %2$s','[%s] Recurring Invoices Automatically Generated'=>'[%s] Factures recurrents generades automàticament','A customer has made a request that requires special attention (B2B, bulk, custom products, special shipping, etc.).'=>'Un client ha fet una sol·licitud que requereix una atenció especial (B2B, a l\'engròs, productes personalitzats, enviament especial, etc.).','A Figma-style flow viewer for mockup screens. Clients can review and comment on project screens before development.'=>'Un visor de flux d\'estil Figma per a maquetes de pantalles. Els clients poden revisar i comentar les pantalles del projecte abans del desenvolupament.','A Page Access Token with <code>pages_read_engagement</code> and <code>read_insights</code> permissions.'=>'Un testimoni d\'accés a la pàgina amb permisos <code>pages_read_engagement</code> i <code>read_insights</code>.','A powerful CRM with AI WhatsApp/Instagram chat, sales funnels, funnel form builder, contact forms, email campaigns, budgets & invoices, mockup flow viewer, social media links, referral system, CTA injection, WooCommerce CTA block, back-in-stock notifications, product calendar, solidarity purchases, and WooCommerce integration for WordPress.'=>'Un potent CRM amb xat d\'IA per WhatsApp/Instagram, embuts de vendes, creador de formularis d\'embuts, formularis de contacte, campanyes de correu electrònic, pressupostos i factures, visor de flux de maquetes, enllaços a xarxes socials, sistema de referències, injecció de crida a l\'acció, bloc de crida a l\'acció de WooCommerce, notificacions de tornada a l\'estoc, calendari de productes, compres solidàries i integració amb WooCommerce per a WordPress.','Abril'=>'Abril','Accept and sign'=>'Accepta i signa','Accept Invitation'=>'Accepta la invitació','Accept orders via chat'=>'Accepta comandes via xat','Accepted'=>'Acceptat','Accepted %s'=>'Acceptat %s','Accepted by'=>'Acceptat per','Accepted on'=>'Acceptat el','Accepted types (.pdf, .jpg...)'=>'Tipus acceptats (.pdf, .jpg...)','Access Denied'=>'Accés denegat','Access restricted'=>'Accés restringit','Access the CRM'=>'Accedir al CRM','Acciones'=>'Accions','Account health'=>'Estat del compte','Accounting'=>'Comptabilitat','Acercar'=>'Acercar','Action not allowed.'=>'Acció no permesa.','Actions'=>'Accions','Activar calendario de productos'=>'Activar calendari de productes','Activar tarifa / descuento especial'=>'Activar tarifa / descompte especial','Activate'=>'Activa','Activating...'=>'Activant...','Active'=>'Actiu','Activity groups'=>'Grups d\'activitats','Actual'=>'Real','Add alternative'=>'Afegeix una alternativa','Add audio'=>'Afegeix àudio','Add audios'=>'Afegeix àudios','Add block'=>'Afegeix un bloc','Add comment'=>'Afegeix un comentari','Add contact'=>'Afegeix un contacte','Add custom fields to checkout for this product'=>'Afegeix camps personalitzats al pagament d\'aquest producte','Add custom links that will appear as large buttons at the top of your social media page.'=>'Afegeix enllaços personalitzats que apareixeran com a botons grans a la part superior de la teva pàgina de xarxes socials.','Add custom links that will appear as large buttons. Format: One link per line as JSON: {"title":"My Link","url":"https://...","description":"Optional"}'=>'Afegeix enllaços personalitzats que apareixeran com a botons grans. Format: Un enllaç per línia com a JSON: {"title":"El meu enllaç","url":"https://...","description":"Opcional"}','Add element'=>'Afegeix un element','Add email addresses for people who are not registered users on this site.'=>'Afegiu adreces de correu electrònic per a persones que no siguin usuaris registrats en aquest lloc.','Add Field'=>'Afegeix un camp','Add field'=>'Afegeix un camp','Add file'=>'Afegeix un fitxer','Add files'=>'Afegeix fitxers','Add group'=>'Afegeix un grup','Add image'=>'Afegeix una imatge','Add images'=>'Afegeix imatges','Add item'=>'Afegeix un element','Add Label'=>'Afegeix una etiqueta','Add Mockup'=>'Afegeix una maqueta','Add New'=>'Afegeix nou','Add new Budget'=>'Afegeix un pressupost nou','Add new Funnel'=>'Afegeix un embut nou','Add New Funnel category'=>'Afegeix una nova categoria d\'embut','Add new Invoice'=>'Afegeix una factura nova','Add New Mockup Flow'=>'Afegeix un nou flux de maqueta','Add new Mockup Flow'=>'Afegeix un nou flux de maqueta','Add new Organization'=>'Afegeix una nova organització','Add new organization'=>'Afegeix una nova organització','Add Option'=>'Afegeix una opció','Add option'=>'Afegeix una opció','Add phase'=>'Afegeix una fase','Add Problem'=>'Afegeix un problema','Add rel=nofollow'=>'Afegeix rel=nofollow','Add Service'=>'Afegeix un servei','Add solidarity purchase'=>'Afegeix una compra solidària','Add Step'=>'Afegeix un pas','Add Testimonial'=>'Afegeix un testimoni','Add video'=>'Afegeix vídeo','Add videos'=>'Afegeix vídeos','Additional Comments'=>'Comentaris addicionals','Additional Comments for AI'=>'Comentaris addicionals per a la IA','Additional Information'=>'Informació addicional','Additional information'=>'Informació addicional','Additional information for: %s'=>'Informació addicional per a: %s','Additional information the AI will use as reference to respond.'=>'Informació addicional que la IA utilitzarà com a referència per respondre.','ADDITIONAL ORDER INFORMATION'=>'INFORMACIÓ ADDICIONAL DE LA COMANDA','Additional Order Information'=>'Informació addicional de la comanda','Additional shipping information'=>'Informació addicional d\'enviament','Address'=>'Adreça','Adds a Gutenberg block for creating Call to Action sections linked to WooCommerce products, categories, tags, or the shop page.'=>'Afegeix un bloc de Gutenberg per crear seccions de crida a l\'acció vinculades a productes, categories, etiquetes o la pàgina de la botiga de WooCommerce.','Adds all variations with their attributes, prices and direct purchase links. Warning: this can significantly increase AI API call costs.'=>'Afegeix totes les variacions amb els seus atributs, preus i enllaços de compra directa. Avís: això pot augmentar significativament els costos de les trucades a l\'API d\'IA.','Adds product categories so the AI can classify and reason about product types.'=>'Afegeix categories de productes perquè la IA pugui classificar i raonar sobre els tipus de productes.','Adds product tags so the AI can identify product features and characteristics.'=>'Afegeix etiquetes de producte perquè la IA pugui identificar les característiques i les característiques del producte.','Admin panel'=>'Panell d\'administració','Advanced CRM fields'=>'Camps avançats de CRM','After'=>'Després','After amount (100 €)'=>'Import després (100 €)','Age range'=>'Rang d\'edat','Agosto'=>'Agost','AI generation failed. Please check your OpenAI API key in settings.'=>'La generació d\'IA ha fallat. Comproveu la vostra clau d\'API d\'OpenAI a la configuració.','AI generation returned empty content. Check debug.log for details. The API might have returned an error or the content was filtered out.'=>'La generació d\'IA ha retornat contingut buit. Consulteu debug.log per obtenir més informació. És possible que l\'API hagi retornat un error o que el contingut s\'hagi filtrat.','AI Model'=>'Model d\'IA','AI Offer Generator'=>'Generador d\'ofertes d\'IA','AI prompt'=>'Sol·licitud d\'IA','AI prompt — CSV format instructions'=>'Sol·licitud d\'IA: instruccions en format CSV','AI Providers'=>'Proveïdors d\'IA','AI-powered WhatsApp and Instagram chat integration'=>'Integració de xat de WhatsApp i Instagram amb intel·ligència artificial','Akismet'=>'Akismet','Akismet status'=>'Estat d\'Akismet','Alejar'=>'Alejar','Alguien'=>'Alguien','Alignment'=>'Alineació','All'=>'Tot','All Budgets'=>'Tots els pressupostos','All Funnel categories'=>'Totes les categories d\'embuts','All Funnels'=>'Tots els embuts','All Invoices'=>'Totes les factures','All Organizations'=>'Totes les organitzacions','All Products'=>'Tots els productes','All Status'=>'Tots els estats','All time'=>'Tots els temps','All Variations'=>'Totes les variacions','All-time trend'=>'Tendència de tots els temps','Allow Multiple Files'=>'Permetre diversos fitxers','Allow search engine indexing on CRM pages'=>'Permetre la indexació dels motors de cerca a les pàgines del CRM','Allow solidarity purchases on this product (does not reduce stock).'=>'Permet compres solidàries en aquest producte (no redueix l\'estoc).','Allow the AI to confirm orders during WhatsApp conversations and send an email notification.'=>'Permet que la IA confirmi les comandes durant les converses de WhatsApp i enviï una notificació per correu electrònic.','Allows a solidarity purchase system on products. Buyers can leave their name visible on the product page. Stock is not reduced.'=>'Permet un sistema de compra solidària en productes. Els compradors poden deixar el seu nom visible a la pàgina del producte. No es redueix l\'estoc.','Allows adding custom fields to checkout page per product. Fields can be configured in the product edit page under "Checkout Fields" tab.'=>'Permet afegir camps personalitzats a la pàgina de pagament per producte. Els camps es poden configurar a la pàgina d\'edició del producte, a la pestanya "Camps de pagament".','Allows administrators to export orders with custom field data to CSV from product pages and product edit screen. Includes column selection and data preview.'=>'Permet als administradors exportar comandes amb dades de camps personalitzats a CSV de